/// <summary>
/// CB223_PalletRounding
/// Batch service class for Post pricing order optimisation
/// </summary>
class METPostPricingOrderOptimisationTaskService extends METSysOperationTaskService
{
    guid    topPickingProcessId;
    SalesId salesId;

}

Method.Source:
/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METPostPricingOrderOptimisationContract</c>.
/// </param>
public void process(METPostPricingOrderOptimisationContract _contract)
{
    METProcMetrics procMetrics = METProcMetrics::construct(METBatchLogOperation::PostPricingOrderOptimisation);

    procMetrics.beginTrace('Process started');

    using (METProcMetricsScope procMetricsScope = METProcMetricsScope::constructWithErrorHandling(procMetrics))
    {
        this.processInternal(_contract);
        procMetrics.endTrace();
    }
}

/// <summary>
/// Process the batch tasks.
/// </summary>
/// <param name = "_readPast">Read past table setting.</param>
public void processTask(boolean _readPast)
{
    str allErrorMessages;
    boolean success;

    Timezone tz = DateTimeUtil::getUserPreferredTimeZone();

    while (this.getSalesIdFromTopPickingQueue(topPickingProcessId, _readPast))
    {
        try
        {
            if (this.salesId)
            {
                SalesTable salesTable = SalesTable::find(this.salesId);
                METSalesTable metSalesTable = METSalesTable::findByRefRecId(salesTable.RecId, true);

                if (salesTable && metSalesTable)
                {                             
                    setPrefix(this.salesId);
                    ttsbegin;
                    // execute optimisation processes after PE pricing update in FO                        
                    success = this.execute(salesTable, metSalesTable);                                         
                    ttscommit;

                    // update sales order processing status if credit management account status is active.
                    if (success)
                    {
                        ttsbegin;
                        // Bug 344903: [MS-MET] PERF - Ops-Sell-Post pricing order optimisation - slow performance
                        // Credit check must be done after optimisation, not before
                        // Trigger proforma confirmation - credit check
                        // The below process has been moved to CreditCheckForListOfSalesorders method
                        //METSalesTable::runCustomCreditCheckForSalesOrder(salesTable, false);
                        this.creditCheckForListOfSalesrders(salesTable);

                        salesTable = SalesTable::find(this.salesId);
                        metSalesTable = METSalesTable::findByRefRecId(salesTable.RecId, true);

                        this.updateSalesOrderProcessingStatus(metSalesTable, salesTable);

                        ttscommit;
                    }
                    else
                    {
                        throw error(strFmt("@MET:PostPricingOrderOptimisationError", this.salesId));
                    }
                }
            }
        }
        catch (Exception::Error)
        {
            //CBNF019_Observability_SalesOrder
            str errorMessage;
            SysInfologEnumerator enumerator;
            SysInfologMessageStruct msgStruct;

            // 1. Extract error messages from the Infolog
            enumerator = SysInfologEnumerator::newData(infolog.copy(1, infologLine()));
            while (enumerator.moveNext())
            {
                msgStruct = new SysInfologMessageStruct(enumerator.currentMessage());
                errorMessage += msgStruct.message() + " ";
            }

            if (this.salesId != '')
            {
                METTelemetrySOPalletRoundingErrorEvent::runTelemetryEvent(this.salesId, errorMessage);
                METTelemetrySOQuotaCheckErrorEvent::runTelemetryEvent(this.salesId, errorMessage);
            }
            //CBNF019_Observability_SalesOrder

            if (allErrorMessages)
            {
                allErrorMessages += '\n';
            }
            allErrorMessages += errorMessage;

            // Catch any exception so that any one error won't bring down
            // the entire process of sales order pallet rounding but will still capture and show the error.
            Global::exceptionTextFallThrough();
        }

    }

    if (allErrorMessages)
    {
        setPrefix("@MET:ErrorInPricing");
        error(allErrorMessages);
    }
}

/// <summary>
/// Initializes the object.
/// </summary>
protected void initialise()
{
    super();

    // get the topPickingProcessId from the contract
    METPostPricingOrderOptimisationContract contract = dataContract as METPostPricingOrderOptimisationContract;
    topPickingProcessId = contract.parmTopPickingProcessId();
}

/// <summary>
/// Executes the main processes pallet rounding, quota min/max and leter credit check.
/// </summary>
/// <param name = "_salesTable">Sales order to process.</param>
/// <param name = "_metSalesTable">Sales order header additional fields</param>
/// <returns>True if all lines processed for pallet rounding and quotas; otherwise, false.</returns>
private boolean execute(SalesTable _salesTable, METSalesTable _metSalesTable)
{
    boolean success = true;
    Timezone tz = DateTimeUtil::getUserPreferredTimeZone();

    // process pallet rounding
    if (SalesParameters::find().METActivatePalletRounding)
    {
        METSalesTablePalletRoundingProcess palletRoundingProcess = METSalesTablePalletRoundingProcess::construct(_salesTable.salesId);
        success = palletRoundingProcess.run();
    }

    if (success)
    {
        // Quota Min/Max trigger
        METSalesTableQuotaProcess quotaProcess = METSalesTableQuotaProcess::construct(_salesTable, _metSalesTable);
        quotaProcess.run();
    }

    return success;
}

/// <summary>
/// Get sales order id to substitute from the top picking queue <c>METPostPricingOrderOptimisationQueue</c>
/// </summary>
/// <param name = "_processId">Guid created and added in the contract <c>METPostPricingOrderOptimisationContract</c></param>
/// <param name = "_readPast">boolean to read past records or not</param>
/// <returns>Get sales order id to substitute</returns>
private SalesId getSalesIdFromTopPickingQueue(guid _processId, boolean _readPast)
{
    METPostPricingOrderOptimisationQueue postQueue;

    #OCCRetryCount
    int backOffWait;
    Microsoft.Dynamics.Ax.Xpp.DeadlockException deadLockException;
    Microsoft.Dynamics.Ax.Xpp.UpdateConflictException updateConflictException;
    Microsoft.Dynamics.Ax.Xpp.TransientSqlConnectionError transientSqlConnectionError;

    postQueue.readPast(_readPast);

    try
    {
        ttsbegin;

        select firstonly pessimisticlock SalesId
        from postQueue
        where postQueue.ProcessId == _processId;

        if (postQueue.RecId)
        {
            this.salesId = postQueue.SalesId;

            postQueue.delete();
        }
        else
        {
            // no sales order id found from top picking queue
            this.salesId = '';
        }

        ttscommit;
    }
    catch (deadLockException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw deadLockException;
            }
        }
        else
        {
            throw deadLockException;
        }
    }
    catch (updateConflictException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw Exception::UpdateConflictNotRecovered;
            }
        }
        else
        {
            throw updateConflictException;
        }
    }
    catch (transientSqlConnectionError)
    {
        if (SysTransientSqlConnectionErrorHandler::retryTransientSqlConnectionError())
        {
            retry;
        }
        else
        {
            throw transientSqlConnectionError;
        }
    }

    return this.salesId;  
}

/// <summary>
/// Update sales order header processing status
/// </summary>
/// <param name = "_metSalesTable">Sales order header additional fields</param>
protected void updateSalesOrderProcessingStatus(METSalesTable _metSalesTable, SalesTable    _salesTable)
{
    ttsbegin;

    if (_metSalesTable)
    {
        _metSalesTable.OrderProcessingStatus = METSalesOrderProcessingStatus::OptimisationCompleted;
        _metSalesTable.SalesLineCount = this.getNumberOfLines(_salesTable);
        _metSalesTable.update();
    }
    ttscommit;
}

/// <summary>
/// Returns the number of sales lines for the specified sales order.
/// </summary>
/// <param name="_salesTable">Sales order record whose lines are to be counted. If null or has an empty SalesId, the method returns 0.</param>
/// <returns>Counter representing the total number of SalesLine records for the given sales order.</returns>
protected Counter getNumberOfLines(SalesTable   _salesTable)
{
    SalesLine   salesLine;
    Counter     lineCount = 0;

    if (!_salesTable || !_salesTable.SalesId)
    {
        return lineCount;
    }

    select count(RecId) from salesLine
        where salesLine.SalesId == _salesTable.SalesId;

    lineCount = salesLine.RecId;

    return lineCount;
}

protected void creditCheckForListOfSalesrders(SalesTable _salesTable)
{
    //boolean credManStatusCheckSetupProf = CredManStatusCheckSetup::exist(CredManHoldType::Credit, CredManDocumentStatusCheck::METCreditCheck, true);;
    boolean credManStatusCheckSetupPost = CredManStatusCheckSetup::exist(CredManHoldType::Credit, CredManDocumentStatusCheck::METCreditCheck, false);
    SalesTable salesTableLoc;
    METSalesTable metSalesTableLoc;
    CredManTable credManTableLoc;
    CredManTrans credManTransLoc;
    SalesLine   salesLineLoc;


    if (credManStatusCheckSetupPost == false)// && credManStatusCheckSetupProf == false)
    {
        // if credit management check is not setup for both posting and proforma, then
        return;
    }

    salesTableLoc.skipDataMethods(true);
    salesTableLoc.skipEvents(true);
    update_recordset salesTableLoc
        setting METCreditCheckSalesOrder = true
        where salesTableLoc.RecId == _salesTable.RecId;

    metSalesTableLoc.skipDataMethods(true);
    metSalesTableLoc = METSalesTable::findBySalesTable(_salesTable.RecId, true);
    metSalesTableloc.CustomCreditCheckExecute = true;
    metSalesTableLoc.doupdate();

    delete_from credManTableLoc
        where credManTableLoc.SalesId == _salesTable.SalesId;  

    delete_from credManTransLoc
        exists join salesLineLoc
            where credManTransLoc.InventTransId == salesLineLoc.InventTransId
                && salesLineLoc.SalesId == _salesTable.SalesId;

    this.performCreditCheck(salesTableLoc.SalesId);
}

/// <summary>
/// The method takes sales order id as parameter, 
/// then build necessary tables for credit check and 
/// trigger the credit check process in order to create credit hold if necessary.
/// </summary>
/// <param name = "_salesId"></param>
protected void performCreditCheck(SalesId _salesId)
{
    SalesTable salesTableLoc = SalesTable::find(_salesId);
    METSalesTable metSalesTable = METSalesTable::findBySalesTable(salesTableLoc.RecId);
    SalesParmUpdate salesParmUpdate;
    SalesParmTable salesParmTable;
    SalesFormletterParmData parmData = SalesFormletterParmData::construct(DocumentStatus::Confirmation);
    SalesTotals salesTotals;
    boolean creditCheckSuccess;

    // Calculate sales totals
    salesTotals = SalesTotals::construct(salesTableLoc, SalesUpdate::All, AccountOrder::None);
    salesTotals.calc();

    //Build sales parm tables
    ttsbegin;
    parmData.parmOnlyCreateParmUpdate(true);
    parmData.createData(false);
    salesParmUpdate = parmData.parmParmUpdate();
    //the proforma flag been disabled after discussion with Akshay.
    //The flag originally added to perform using salesformletter
    //Now as we are not using salesformetter class we can skip this flag.
    //salesParmUpdate.Proforma = NoYes::Yes;
    salesParmUpdate.doupdate();

    salesParmTable.clear();
    salesParmTable.TransDate                = systemDateGet();
    salesParmTable.Ordering                 = DocumentStatus::Confirmation;
    salesParmTable.ParmJobStatus            = ParmJobStatus::Waiting;
    salesParmTable.salesId                  = salesTableLoc.salesId;
    salesParmTable.salesName                = salesTableLoc.salesName;
    salesParmTable.DeliveryName             = salesTableLoc.DeliveryName;
    salesParmTable.DeliveryPostalAddress    = salesTableLoc.DeliveryPostalAddress;
    salesParmTable.CustAccount              = salesTableLoc.CustAccount;
    salesParmTable.CurrencyCode             = salesTableLoc.CurrencyCode;
    salesParmTable.InvoiceAccount           = salesTableLoc.InvoiceAccount;
    salesParmTable.ParmId                   = salesParmUpdate.ParmId;
    salesParmTable.insert();
    ttscommit;

    // run credit check and create credit hold if necessary.
    CredManCreditControl  creditControl =  CredManCreditControl::newFromDocumentStatusCheck(CredManDocumentStatusCheck::Confirmation);
    creditControl.parmSalesTable(salesTableLoc);
    creditControl.parmReleaseReasonMap(null);
    creditControl.parmSalesParmTable(salesParmTable);
    creditControl.parmSalesParmUpdate(salesParmUpdate);
    creditControl.parmSalesTotals(salesTotals);
    ttsbegin;
    creditCheckSuccess = creditControl.check();
    creditControl.createCreditHold();
    ttscommit;

    //CBNF019_Observability (Credit Check) task 396221
    if (creditCheckSuccess)
    {
        METTelemetrySOCreditCheckInfoEvent::runTelemetryEvent(salesTableLoc.salesId);
    }
    else
    {
        METTelemetrySOCreditCheckErrorEvent::runTelemetryEvent(salesTableLoc.salesId, strFmt("@MET:CreditCheckFail", salesTableLoc.salesId));
    }
}
